void il3945_config_ap ( struct il_priv * il ) { struct ieee80211_vif * vif = il -> vif ; int rc = 0 ; if ( test_bit ( S_EXIT_PENDING , & il -> status ) ) { return ; } if ( ! ( il_is_associated ( il ) ) ) { il -> staging . filter_flags &= ~ RXON_FILTER_ASSOC_MSK ; il3945_commit_rxon ( il ) ; rc = il_send_rxon_timing ( il ) ; if ( rc ) { IL_WARN ( "C_RXON_TIMING failed - " "Attempting to continue.\n" ) ; } il -> staging . assoc_id = 0 ; if ( vif -> bss_conf . use_short_preamble ) { il -> staging . flags |= RXON_FLG_SHORT_PREAMBLE_MSK ; } else { il -> staging . flags &= ~ RXON_FLG_SHORT_PREAMBLE_MSK ; } if ( il -> staging . flags & RXON_FLG_BAND_24G_MSK ) { if ( vif -> bss_conf . use_short_slot ) { il -> staging . flags |= RXON_FLG_SHORT_SLOT_MSK ; } else { il -> staging . flags &= ~ RXON_FLG_SHORT_SLOT_MSK ; } } il -> staging . filter_flags |= RXON_FILTER_ASSOC_MSK ; il3945_commit_rxon ( il ) ; } il3945_send_beacon_cmd ( il , NULL ) ; } 